const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const defaults={collections:['Personal','Work','Experiments'],overrides:{},custom:[],order:[],favorites:[],hidden:[],name:'dock',theme:matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'};
let state;try{state={...structuredClone(defaults),...JSON.parse(localStorage.getItem('dock-v1')||'{}')}}catch{state=structuredClone(defaults)}
let discovered=[],scope='All projects',query='',dragId=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={moon:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M20 14a8 8 0 0 1-10-10 8.5 8.5 0 1 0 10 10Z"/></svg>',sun:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>',folder:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M3 7V5a1 1 0 0 1 1-1h5l3 3h8a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V7Z"/></svg>'};
function save(){localStorage.setItem('dock-v1',JSON.stringify(state));apply();render()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function apply(){const dark=state.theme==='dark';document.documentElement.classList.toggle('dark',dark);document.querySelector('meta[name="theme-color"]').content=dark?'#000000':'#ffffff';$('#brandname').textContent=state.name;$('#theme-toggle').innerHTML=dark?icons.sun:icons.moon;$('#theme-toggle').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`)}
function projects(){return [...discovered,...state.custom].filter(p=>!state.hidden.includes(p.id)).map(p=>({...p,...state.overrides[p.id]}))}
function safeURL(v){try{const url=new URL(v,location.href);return ['http:','https:'].includes(url.protocol)?url.href:null}catch{return null}}
function render(){const all=projects();$('#project-count').textContent=all.length;$('#collection-filter').innerHTML=['All projects','Favorites',...state.collections].map(c=>`<option value="${esc(c)}" ${scope===c?'selected':''}>${esc(c)}</option>`).join('');const list=all.filter(p=>(scope==='All projects'||scope==='Favorites'&&state.favorites.includes(p.id)||p.collection===scope)&&`${p.name} ${p.description} ${p.collection}`.toLowerCase().includes(query.toLowerCase()));list.sort((a,b)=>(state.order.indexOf(a.id)<0?999:state.order.indexOf(a.id))-(state.order.indexOf(b.id)<0?999:state.order.indexOf(b.id)));
$('#projects').innerHTML=list.map(p=>`<article class="project-row" draggable="true" data-id="${esc(p.id)}"><span class="drag-handle" aria-hidden="true" title="Drag to reorder">⠿</span><span class="project-icon" aria-hidden="true">${icons.folder}</span><a class="project-link" href="${esc(safeURL(p.url)||'#')}" data-project="${esc(p.id)}"><span class="project-name">${esc(p.name)}${state.favorites.includes(p.id)?'<span class="favorite-mark" aria-label="Favorite">☆</span>':''}</span>${p.description?`<span class="project-description">${esc(p.description)}</span>`:''}</a><span class="project-collection">${esc(p.collection)}</span><button class="project-menu" data-edit="${esc(p.id)}" aria-label="Edit ${esc(p.name)}">···</button></article>`).join('')+(list.length?'':`<div class="empty"><p>${query?'No projects match your search.':'No projects here yet.'}</p>${query?'':'<button class="secondary" id="empty-add">Add project</button>'}</div>`);
$$('[data-edit]').forEach(el=>el.onclick=()=>projectModal(el.dataset.edit));if($('#empty-add'))$('#empty-add').onclick=()=>projectModal();$$('[data-project]').forEach(el=>el.onclick=e=>{if(!safeURL(projects().find(p=>p.id===el.dataset.project)?.url)){e.preventDefault();projectModal(el.dataset.project)}});
$$('.project-row').forEach(el=>{el.ondragstart=e=>{dragId=el.dataset.id;e.dataTransfer.setData('text/plain',dragId);el.classList.add('dragging')};el.ondragend=()=>{$$('.dragging,.drop-target').forEach(x=>x.classList.remove('dragging','drop-target'));dragId=null};el.ondragover=e=>{e.preventDefault();el.classList.add('drop-target')};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=e=>{e.preventDefault();if(!dragId||dragId===el.dataset.id)return;const ids=list.map(p=>p.id).filter(x=>x!==dragId);ids.splice(ids.indexOf(el.dataset.id),0,dragId);state.order=[...ids,...all.map(p=>p.id).filter(x=>!ids.includes(x))];dragId=null;save();toast('Project order saved')}})}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button id="close-modal" aria-label="Close dialog">×</button></div>${body}`;$('#close-modal').onclick=()=>$('#modal').close();if(!$('#modal').open)$('#modal').showModal()}
function projectModal(id){const p=projects().find(p=>p.id===id)||{name:'',description:'',url:'',collection:state.collections.includes(scope)?scope:state.collections[0]};modal(id?'Edit project':'Add project',`<form id="project-form"><label>Name<input name="name" required maxlength="80" value="${esc(p.name)}" placeholder="Project name"></label><label>URL or project path<input name="url" required value="${esc(p.url)}" placeholder="projects/my-project/ or https://…"></label><label>Description <span style="color:var(--muted)">(optional)</span><textarea name="description" maxlength="180">${esc(p.description)}</textarea></label><label>Collection<select name="collection">${state.collections.map(c=>`<option ${c===p.collection?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${id?`<div class="backup-row"><button type="button" class="secondary" id="favorite-project">${state.favorites.includes(id)?'Remove favorite':'Add to favorites'}</button><button type="button" class="secondary" id="move-up" ${projects().length<2?'disabled':''}>Move to top</button></div>`:'<p>To add repository files, ask Codex to create a folder in <code>projects/</code>.</p>'}<div class="modal-actions">${id?'<button type="button" class="secondary danger" id="remove-project">Remove</button>':''}<button type="button" class="secondary" id="cancel">Cancel</button><button class="primary" type="submit">${id?'Save':'Add project'}</button></div></form>`);$('#cancel').onclick=()=>$('#modal').close();$('#project-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.name=data.name.trim();data.url=data.url.trim();if(!data.name||!data.url||!safeURL(data.url)){toast('Enter a name and a valid URL or project path.');return}if(id)state.overrides[id]={...state.overrides[id],...data};else state.custom.push({...data,id:crypto.randomUUID(),updated:new Date().toISOString()});save();$('#modal').close();toast(id?'Project updated':'Project added')};if(id){$('#remove-project').onclick=()=>{state.hidden.push(id);save();$('#modal').close();toast('Removed from hub. Repository files are kept.')};$('#favorite-project').onclick=()=>{state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();projectModal(id)};$('#move-up').onclick=()=>{state.order=[id,...projects().map(p=>p.id).sort((a,b)=>(state.order.indexOf(a)<0?999:state.order.indexOf(a))-(state.order.indexOf(b)<0?999:state.order.indexOf(b))).filter(x=>x!==id)];save();toast('Moved to top')}}}
function collectionModal(){modal('Your collections',`<p>Change a project’s collection from its edit menu.</p><div id="collection-editor">${state.collections.map((c,i)=>`<div style="display:flex;gap:8px;align-items:center"><input aria-label="Collection name" id="collection-${i}" value="${esc(c)}" maxlength="40"><button class="secondary" data-rename="${i}">Save</button><button class="secondary" data-remove="${i}" aria-label="Remove ${esc(c)}">×</button></div>`).join('')}</div><form id="collection-form"><label>New collection<input name="name" required maxlength="40" placeholder="Collection name"></label><div class="modal-actions"><button class="primary">+ Create collection</button></div></form>`);$('#collection-form').onsubmit=e=>{e.preventDefault();const n=new FormData(e.target).get('name').trim();if(!n||state.collections.includes(n)||['All projects','Favorites','Recently added'].includes(n)){toast('Choose a unique collection name.');return}state.collections.push(n);save();collectionModal()};$$('[data-rename]').forEach(b=>b.onclick=()=>{const i=+b.dataset.rename,old=state.collections[i],n=$(`#collection-${i}`).value.trim();if(!n||['All projects','Favorites','Recently added'].includes(n)||state.collections.includes(n)&&n!==old){toast('Choose a unique collection name.');return}projects().filter(p=>p.collection===old).forEach(p=>state.overrides[p.id]={...state.overrides[p.id],collection:n});state.collections[i]=n;if(scope===old)scope=n;save();collectionModal()});$$('[data-remove]').forEach(b=>b.onclick=()=>{if(state.collections.length===1){toast('Keep at least one collection.');return}const old=state.collections.splice(+b.dataset.remove,1)[0];projects().filter(p=>p.collection===old).forEach(p=>state.overrides[p.id]={...state.overrides[p.id],collection:state.collections[0]});if(scope===old)scope='All projects';save();collectionModal()})}
function settings(){modal('Settings',`<label>Workspace name<input id="setting-name" value="${esc(state.name)}" maxlength="24"></label><label>Appearance<select id="setting-theme"><option value="light" ${state.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.theme==='dark'?'selected':''}>Dark</option></select></label><div class="backup-row"><button class="secondary" id="manage-collections">Manage collections</button></div><details><summary>Backup & project discovery</summary><p>New folders in <code>projects/</code> appear after each push and deployment. Links and preferences added here are saved in this browser.</p><div class="backup-row"><button class="secondary" id="export">Export settings</button><button class="secondary" id="import">Import settings</button><input id="import-file" type="file" accept="application/json" hidden style="display:none"></div>${state.hidden.length?'<button class="secondary" id="restore" style="margin-top:12px">Restore removed projects</button>':''}</details><div class="modal-actions"><button class="primary" id="settings-save">Save</button></div>`);$('#manage-collections').onclick=collectionModal;$('#settings-save').onclick=()=>{state.name=$('#setting-name').value.trim()||'dock';state.theme=$('#setting-theme').value;save();$('#modal').close();toast('Settings saved')};$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='dock-settings.json';a.click();URL.revokeObjectURL(a.href)};$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(!Array.isArray(data.collections)||!data.collections.length||!data.collections.every(x=>typeof x==='string')||!Array.isArray(data.custom)||!data.custom.every(x=>x&&typeof x.id==='string'&&typeof x.name==='string')||!Array.isArray(data.favorites)||!data.overrides||typeof data.overrides!=='object'||Array.isArray(data.overrides))throw Error();for(const key of ['hidden','order'])if(data[key]&&!Array.isArray(data[key]))throw Error();state={...structuredClone(defaults),...data,name:typeof data.name==='string'?data.name:'dock',theme:data.theme==='dark'?'dark':'light'};save();$('#modal').close();toast('Settings imported')}catch{toast('Choose a valid Dock settings backup.')}};if($('#restore'))$('#restore').onclick=()=>{state.hidden=[];save();settings();toast('Projects restored')}}
$('#settings').onclick=settings;$('#theme-toggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';save()};$('#new-project').onclick=()=>projectModal();$('#search').oninput=e=>{query=e.target.value;render()};$('#collection-filter').onchange=e=>{scope=e.target.value;render()};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();$('#search').focus()}});$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};
async function refresh(){try{const response=await fetch('projects.json?t='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json();if(JSON.stringify(data)!==JSON.stringify(discovered)){discovered=data;for(const p of data)if(p.collection&&!state.collections.includes(p.collection))state.collections.push(p.collection);render()}$('#discovery-label').textContent=''}catch{$('#discovery-label').textContent='Could not refresh projects. Retrying…'}}apply();render();refresh();setInterval(refresh,15000);
